INSERT INTO questions (id, sort_order, question, type, choices, answer, is_active) VALUES
('q1_new', 1, 'あなたは警察に手配された状態でセッションを退出（ログアウト）した後、再参加して「インタラクティブジョブ」に就こうとした。このとき、ロールプレイ上で課される制限は何か。', 'radio', '["手配状態が引き継がれるため、役職（ジョブ）を変更することはできず、警察から逃れることはできない。","手配状態は引き継がれるが、市民ジョブは変更可能であり、警察から隠れてRPを続行できる。","ジョブ変更の制限はなく、警察の追跡から逃れられたとみなし、通常通りRPを再開できる。","インタラクティブジョブの資格を失い、すべてのジョブへの参加が禁止される。"]', '"手配状態が引き継がれるため、役職（ジョブ）を変更することはできず、警察から逃れることはできない。"', 1),
('q2_new', 2, '環状交差点（ラウンドアバウト）に進入しようとしている。手前にYIELD標識があり、交差点内にはあなたの走行に影響を与えない他の車が走行している。このとき、最も適切な行動はどれか。', 'radio', '["一時停止せず、減速してそのまま進入する。","環状交差点の進入は信号のない交差点と同様に、右側の車に優先権を譲る。","交差点内の車が完全に通り過ぎるのを待ってから進入する。","安全のため、一時停止してから進入する。"]', '"一時停止せず、減速してそのまま進入する。"', 1),
('q3_new', 3, 'あなたがもし他人と事故を起こしてしまった。このとき、最初に取るべき行動はどれか。', 'radio', '["自分が負傷していないことを確認し、車を降りて、すぐに警察（ゲーム内）に通報する。","相手の車に体当たりして、修理代の代わりに慰謝料を請求すると叫ぶ。","保険に入っていないので、その場から立ち去る。","すぐにサーバーホストに事故を起こしてしまった旨を報告する。"]', '"自分が負傷していないことを確認し、車を降りて、すぐに警察（ゲーム内）に通報する。"', 1),
('q4_new', 4, 'もしあなたが荒らしや妨害などの行為をしている人を目撃した。ホストや運営はそれらに気づいていない。このとき、最初に取るべき行動はどれか。', 'radio', '["荒らし行為を無視し、見なかったことにしてロールプレイを継続する。","ゲーム内チャットで相手に直接説教し、行為をやめるよう警告する。","荒らし行為の証拠（スクリーンショットや録画など）を確保し、ロールプレイを続けながら運営・ホストへ報告する。"]', '"荒らし行為の証拠（スクリーンショットや録画など）を確保し、ロールプレイを続けながら運営・ホストへ報告する。"', 1),
('q5_new', 5, 'あなたは交差点に入った時に、後ろから緊急車両が接近してくることに気づいた。このとき、どのように対処すべきか。（短文回答）', 'text', NULL, NULL, 1),
('q6_new', 6, 'あなたは運転中に他のプレイヤーの車にTailgating（執拗に付いていく行為）を行い、警察に目撃された。あなたの現在の違反回数は「2回」だ。この違反に対する不服申し立ては可能か。', 'radio', '["可能である。ただし、違反回数が倍（4回）としてカウントされる。","可能である。違反回数が6回に達する前であれば、不服申し立てが可能である。","可能ではない。違反回数が3回を超えてからでなければ申し立てはできない。","可能ではない。危険運転の禁止は、不服申し立ての対象外である。"]', '"可能ではない。危険運転の禁止は、不服申し立ての対象外である。"', 1),
('q7_new', 7, '駐車する場所として適切な場所を選択してください。', 'checkbox', '["バーガーハウスの駐車場。","交差点の真ん中。","広い路肩。","交差点のすぐ手前。"]', '["バーガーハウスの駐車場。","広い路肩。"]', 1),
('q8_new', 8, 'あなたは現在、街の中心部にある大きな交差点の角で車をスポーンさせたい。近くにガソリンスタンドの駐車場と、何もない広々とした草原（空き地）、そして交通量の少ない路肩がある。この状況で、あなたが車をスポーンさせられる唯一の場所はどこか。', 'radio', '["交通量の少ない路肩。","何もない広々とした空き地（草原）。","ガソリンスタンドの駐車場。","交差点の角。"]', '"何もない広々とした空き地（草原）。"', 1),
('q9_new', 9, 'あなたは踏切を通過しようとしている。踏切内で停車や衝突事故が起こった場合、ルールに照らして最も適切な行動はどれか。', 'radio', '["踏切事故はFRP（失敗ロールプレイ）に該当するため、即座にサーバーを退出する。","踏切では一時停止をする必要がある。事故が起きたら踏切から離れたところで通報する。","踏切では一時停止する必要はない。事故が起こった場合は、当て逃げとみなされないよう、踏切から離れたところで警察に通報する。","安全のため、一時停止してから通過し、事故の場合はすぐに警察に連絡する。"]', '"踏切では一時停止をする必要がある。事故が起きたら踏切から離れたところで通報する。"', 1),
('q10_new', 10, '違反切符は月何回が上限か。', 'radio', '["3回","6回","8回","10回"]', '"6回"', 1);
